pub async fn load_order_details(
    pool: &PgPool,
    tracker: &Tracker,
    orders: Vec<OrderRow>,
) -> Result<Vec<OrderView>, sqlx::Error> {
    // Build pages one at a time, so a shared item cache can be added later without locking.
    assert!(
        !PAGE_IN_PROGRESS.swap(true, Ordering::SeqCst),
        "another page is being built"
    );
    let page = load_page(pool, tracker, orders).await;
    PAGE_IN_PROGRESS.store(false, Ordering::SeqCst);
    page
